    .update(JSON.stringify(event))                     // re-serialized bytes
    .digest('hex');

  if (expected !== signature) {
    return new Response('bad signature', { status: 400 });
  }

  if (seen.has(event.id)) return new Response('ok');

  await applyEvent(event);                             // side effects inline
  seen.add(event.id);
